package com.smartfix.communitybridge;
import org.springframework.stereotype.Service;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.web.client.*;import org.springframework.http.client.SimpleClientHttpRequestFactory;import org.springframework.core.ParameterizedTypeReference;import com.smartfix.auth.security.SmartFixUserDetails;import java.util.*;
@Service @ConditionalOnProperty(name="smartfix.community.events.enabled",havingValue="true")
public class RemoteThreadClient {
 private final CommunityIdentityClient identity;private final RestClient http;
 public RemoteThreadClient(CommunityIdentityClient identity){this.identity=identity;var f=new SimpleClientHttpRequestFactory();f.setConnectTimeout(1000);f.setReadTimeout(3000);http=RestClient.builder().baseUrl("http://127.0.0.1:19092/internal/community/v1").requestFactory(f).build();}
 public Map<String,Object> detail(SmartFixUserDetails actor){Map<String,Object> q=http.get().uri("/questions/900000000001").headers(h->h.setBearerAuth(identity.issue(actor))).retrieve().body(new ParameterizedTypeReference<>(){});if(q==null)throw new IllegalStateException("Missing question");
  List<Map<String,Object>> answers=(List<Map<String,Object>>)q.get("answers");var ids=new LinkedHashSet<Long>();ids.add(((Number)q.get("author_id")).longValue());answers.forEach(a->ids.add(((Number)a.get("author_id")).longValue()));var names=new HashMap<Long,String>();var list=new ArrayList<>(ids);for(int i=0;i<list.size();i+=50)names.putAll(identity.displayNames(list.subList(i,Math.min(i+50,list.size()))));q.put("authorDisplayName",names.getOrDefault(((Number)q.get("author_id")).longValue(),"Campus member"));answers.forEach(a->a.put("authorDisplayName",names.getOrDefault(((Number)a.get("author_id")).longValue(),"Campus member")));return q;
 }
 public void answer(SmartFixUserDetails actor,UUID key,String body){try{http.post().uri("/questions/900000000001/answers").headers(h->{h.setBearerAuth(identity.issue(actor));h.set("Idempotency-Key",key.toString());}).body(Map.of("body",body)).retrieve().toBodilessEntity();}catch(ResourceAccessException uncertain){try{Map<?,?> result=http.post().uri("/commands/lookup").headers(h->h.setBearerAuth(identity.issue(actor))).body(Map.of("operation","ANSWER","key",key.toString())).retrieve().body(Map.class);if(result!=null&&"COMPLETED".equals(result.get("status")))return;}catch(RestClientException ignored){}throw uncertain;}}
}
